(function() {
    console.log(" Nova AI Translator Active!");

    const style = document.createElement('style');
    style.innerHTML = `
        @keyframes rotate { 100% { transform: rotate(360deg); } }
        #nova-container { position: fixed; bottom: 20px; right: 20px; z-index: 9999999; font-family: sans-serif; user-select: none; touch-action: none; }
        #nova-btn { background: #ea4335; color: white; padding: 10px 15px; border-radius: 50px; cursor: move; font-weight: bold; border: none; box-shadow: 0 4px 10px rgba(0,0,0,0.2); display: flex; align-items: center; gap: 5px; font-size: 14px; }
        #nova-btn:disabled { background: #999; cursor: wait; }
        #nova-menu { display: none; background: #fff; border: 1px solid #eee; padding: 5px; border-radius: 12px; margin-bottom: 10px; box-shadow: 0 5px 15px rgba(0,0,0,0.15); position: absolute; bottom: 100%; right: 0; min-width: 120px; }
        #nova-menu div { padding: 8px 12px; cursor: pointer; color: #333; font-size: 13px; border-bottom: 1px solid #f0f0f0; }
        #nova-menu div:hover { background: #fce8e6; color: #d32f2f; }
        .nova-loader { width: 14px; height: 14px; border: 2px solid #fff; border-top: 2px solid transparent; border-radius: 50%; animation: rotate 1s linear infinite; }
    `;
    document.head.appendChild(style);

    // ২. UI রেন্ডার
    const langMap = { "tr": "Turkish", "bn": "Bengali", "en": "English", "hi": "Hindi", "es": "Spanish", "ar": "Arabic" };
    const container = document.createElement('div');
    container.id = 'nova-container';
    container.innerHTML = `<div id="nova-menu"></div><button id="nova-btn">🌐 Trans</button>`;
    document.body.appendChild(container);

    const menu = document.getElementById('nova-menu');
    const btn = document.getElementById('nova-btn');
    let targetLang = 'bn';

    for (let code in langMap) {
        let div = document.createElement('div');
        div.innerText = langMap[code];
        div.onclick = (e) => { e.stopPropagation(); targetLang = code; menu.style.display = 'none'; startTranslation(); };
        menu.appendChild(div);
    }

    // ৩. ড্র্যাগ লজিক
    let isDragging = false, startX, startY, initialLeft, initialTop;
    function dragStart(e) {
        isDragging = false;
        let evt = e.type === 'touchstart' ? e.touches[0] : e;
        startX = evt.clientX; startY = evt.clientY;
        let rect = container.getBoundingClientRect();
        initialLeft = rect.left; initialTop = rect.top;
        document.addEventListener(e.type === 'touchstart' ? 'touchmove' : 'mousemove', dragMove);
        document.addEventListener(e.type === 'touchstart' ? 'touchend' : 'mouseup', dragEnd);
    }
    function dragMove(e) {
        let evt = e.type === 'touchmove' ? e.touches[0] : e;
        if (Math.abs(evt.clientX - startX) > 5 || Math.abs(evt.clientY - startY) > 5) {
            isDragging = true;
            container.style.right = 'auto'; container.style.bottom = 'auto';
            container.style.left = (initialLeft + (evt.clientX - startX)) + 'px';
            container.style.top = (initialTop + (evt.clientY - startY)) + 'px';
        }
    }
    function dragEnd() { document.removeEventListener('mousemove', dragMove); document.removeEventListener('touchmove', dragMove); }
    btn.onmousedown = dragStart; btn.ontouchstart = dragStart;
    btn.onclick = () => { if (!isDragging) menu.style.display = menu.style.display === 'block' ? 'none' : 'block'; };

    // ৪. ট্রান্সলেশন ইঞ্জিন
    async function startTranslation() {
        btn.disabled = true;
        btn.innerHTML = '<span class="nova-loader"></span> ';

        const translateNode = async (node) => {
            if (node.nodeType === 3 && node.nodeValue.trim().length > 1) {
                let text = node.nodeValue.trim();
                try {
                    let res = await fetch(`https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${targetLang}&dt=t&q=${encodeURIComponent(text)}`);
                    let data = await res.json();
                    if(data[0]) node.nodeValue = data[0].map(p => p[0]).join('');
                } catch(e) {}
            } else if (node.nodeType === 1 && !['SCRIPT', 'STYLE', 'CODE'].includes(node.tagName)) {
                for (let child of node.childNodes) await translateNode(child);
            }
        };
        translateNode(document.body);

        setTimeout(() => {
            btn.disabled = false;
            btn.innerHTML = '🌐 Trans';
        }, 7000);
    }
})();
